#include <deque>
#include <algorithm>

int main() {
    std::deque<int> d = {5, 2, 8, 1};

    // Deque iterators are Random Access
    // Allows use of algorithms requiring RA iterators, like sort
    std::sort(d.begin(), d.end()); 

    // Arithmetic is valid, but complex internally
    auto it_end = d.begin() + 3;

    // auto ptr = &(*it_end); // DANGER: Do not rely on internal pointer stability
                            // or treat the iterator as a raw pointer across blocks

    return 0;
}
